int n=0;void Check(bool b,string s){if(!b)throw new Exception(s);n++;Console.WriteLine("PASS "+s);}
using var native=ModuleDefinition.ReadModule(args[0]);
bool Calls(MethodDefinition method,string name)=>method.Body.Instructions.Any(i=>i.Operand is MethodReference r&&r.Name==name);
var scroll=native.Types.Single(t=>t.Name=="TraitScrollStatic").Methods.Single(m=>m.Name=="OnRead");
Check(Calls(scroll,"ModNum")&&Calls(scroll,"ProcAt"),"native scroll consumption precedes the shared effect path");
Check(scroll.Body.Instructions.First(i=>i.Operand is MethodReference{Name:"ModNum"}).Offset<scroll.Body.Instructions.First(i=>i.Operand is MethodReference{Name:"ProcAt"}).Offset,"effect hook does not consume a second scroll");
Check(Calls(native.Types.Single(t=>t.Name=="Act").Methods.Single(m=>m.Name=="Perform"&&m.Parameters.Count==0),"ProcAt"),"native spell performance reaches the same effect path");
var chara=native.Types.Single(t=>t.Name=="Chara");
var revive=chara.Methods.Single(m=>m.Name=="Revive");
var predicate=chara.NestedTypes.SelectMany(t=>t.Methods).Single(m=>m.HasBody&&m.Body.Instructions.Any(i=>i.Operand is MethodReference{Name:"get_SelfWeight"})&&m.Body.Instructions.Any(i=>i.Operand is MethodReference{Name:"get_WeightLimit"}));
foreach(var name in new[]{"get_IsContainer","get_SelfWeight","get_WeightLimit","get_CanBeDropped","get_c_lockLv"})Check(predicate.Body.Instructions.Any(i=>i.Operand is MethodReference r&&r.Name==name),"native overweight predicate retains "+name);
Check(predicate.Body.Instructions.Any(i=>i.Operand is TypeReference{Name:"TraitChestPractice"}),"native practice-chest exception remains");
var callbacks=native.Types.Single(t=>t.Name=="Scene").NestedTypes.SelectMany(t=>t.Methods).Where(m=>m.HasBody).ToArray();
foreach(var marker in new[]{"pc_revive_town","pc_deathChoice","crawlup"})Check(callbacks.Count(m=>m.Body.Instructions.Any(i=>i.Operand as string==marker))==1,"one native death callback for "+marker);
var getRevived=chara.Methods.Single(m=>m.Name=="GetRevived");
Check(getRevived.Body.Instructions.Count(i=>i.Operand is MethodReference{Name:"get_pc"}&&i.Next?.Operand is FieldReference{Name:"pos"})==1,"one native resurrection location anchor");
var host=new ElinNetHost();NetSession.Instance.Connection=host;var zone=EClass._zone;zone.uid=20;
var owner=EClass.pc=new Chara{uid=1,currentZone=zone,pos=new(){x=4,z=8}};EClass.game.cards.globalCharas[1]=owner;
