var tent=Item(10,101,owner);var ordinary=Item(11,100,owner);var box=Item(12,999,owner,true);var nested=Item(13,101,box);var locked=Item(14,999,owner,true);locked.c_lockLv=1;var protectedItem=Item(15,101,locked);var fixedItem=Item(16,101,owner);fixedItem.trait.CanBeDropped=false;
var practice=Item(17,999,owner,true);practice.c_lockLv=1;practice.trait=new TraitChestPractice();var trainingItem=Item(18,101,practice);
var site=PlayerDeathRecovery.Capture(owner);owner.isDead=true;ElinDelta.IsApplying=true;PlayerDeathRecovery.DropOverweight(owner,site);
Check(zone.Ground.Select(t=>t.uid).SequenceEqual(new[]{10,13,18}),"early death drop uses vanilla eligibility including nested and locked inventory");
Check(zone.Ground.All(t=>t.ignoreAutoPick&&t.pos.x==4&&t.pos.z==8)&&zone.Simulated,"drops retain death position, disable auto pickup and use authoritative simulation");
Check(ElinDelta.IsApplying&&owner.things.LastAccessible==false,"drop scope restores replay state and visits inaccessible inventory as vanilla does");ElinDelta.IsApplying=false;
PlayerDeathRecovery.DropOverweight(owner,site);Check(zone.Ground.Count==3,"repeat death recovery cannot clone or redrop moved items");
Check(PlayerDeathRecovery.Capture(owner)==null,"already dead character cannot start another drop");
var remote=new Chara{uid=2,Remote=true,currentZone=zone,c_wasInPcParty=true};host.ActiveRemoteCharas[1]=remote;EClass.game.cards.globalCharas[2]=remote;
owner.isDead=false;var remoteSite=PlayerDeathRecovery.Capture(remote);remote.isDead=true;remote.currentZone=null;PlayerDeathRecovery.DropOverweight(remote,remoteSite);
Check(PlayerDeathRecovery.RescueTarget(owner,owner)==remote,"removed remote-player body is eligible on its recorded death floor");
var otherZone=new Zone{uid=21};EClass._zone=otherZone;owner.currentZone=otherZone;Check(PlayerDeathRecovery.RescueTarget(owner,owner)==null,"same-floor rescue priority excludes distant players, leaving native fallback");EClass._zone=zone;owner.currentZone=zone;
