Check(remote.pos.x==owner.pos.x&&remote.IsPCParty,"rescue returns remote player near caster and to party");PlayerRecoveryPatch.EndEffect(scope);Check(ElinDelta.IsApplying,"effect finalizer restores outer replay state");ElinDelta.IsApplying=false;
Check(PlayerRecoveryPatch.Resurrection(EffectId.Revive,owner,owner,out scope),"without dead humans native NPC resurrection selection is retained");PlayerRecoveryPatch.EndEffect(scope);
var npc=new Chara{uid=3,isDead=true};host.Delta.Items.Clear();
PlayerRecoveryPatch.Resurrection(EffectId.Revive,owner,owner,out scope);npc.Revive(owner.pos,true);PlayerRecoveryPatch.EndEffect(scope);
Check(host.Delta.Items.OfType<CharaReviveDelta>().Count()==1,"native NPC resurrection also publishes its chosen result");
Check(PlayerRecoveryPatch.Resurrection(EffectId.Other,owner,owner,out scope)&&scope==null,"other spell effects untouched");
