PlayerRecoveryPatch.Resurrection(EffectId.Revive,remote,remote,out scope);PlayerRecoveryPatch.EndEffect(scope);
Check(!owner.isDead&&owner.pos.x==9&&host.Delta.Items.Count==1,"client caster rescues host at client location through the same effect route");
Check(dialog.Closed&&!EClass.player.deathDialog&&!PlayerDeathDialogue.StillDead(),"rescue closes only tracked death dialog and invalidates stale native callbacks");
owner.isDead=true;Check(PlayerDeathDialogue.StillDead(),"unrescued player can still choose native crawl-home without a scroll");
// No standalone client request may resurrect someone else's character.
var bad=new CharaReviveDelta{Owner=owner,LastWords=null,Pos=new(){X=1,Z=1}};bad.Apply(host);Check(owner.isDead,"client cannot forge crawl-home for the host");
remote.isDead=true;remote.currentZone=null;var crawl=new CharaReviveDelta{Owner=remote,LastWords="bye",Pos=new(){X=3,Z=4}};crawl.Apply(host);Check(!remote.isDead&&remote.Graves==1,"normal own-character crawl-home request remains supported");
var client=new ElinNetClient();NetSession.Instance.Connection=client;EClass.pc=remote;remote.isDead=true;var beforeRevives=remote.Revives;
var result=new CharaReviveDelta{Owner=remote,LastWords=null,Pos=new(){X=9,Z=12}};result.Apply(client);result.Apply(client);
Check(!remote.isDead&&remote.Revives==beforeRevives+1&&client.Delta.Items.Count==0,"client applies authoritative rescue once without sending another revive request");
var code=PlayerRecoveryPatch.ReviveNearCaster(new[]{new CodeInstruction(OpCodes.Call,AccessTools.PropertyGetter(typeof(EClass),nameof(EClass.pc))),new CodeInstruction(OpCodes.Ldfld,AccessTools.Field(typeof(Card),nameof(Card.pos)))}).ToArray();
Check(code[0].operand.Equals(AccessTools.Method(typeof(PlayerRecoveryPatch),nameof(PlayerRecoveryPatch.ResurrectionOrigin))),"native NPC resurrection location routes to actual caster only");
NetSession.Instance.Connection=null;Check(PlayerDeathRecovery.Capture(remote)==null&&PlayerDeathDialogue.StillDead(),"solo death and dialogue retain vanilla paths");
Console.WriteLine($"{n} checks passed; native metadata checked, game boundaries simulated.");
